import sys

import heapq

class Shuttle:
    def __init__(self, n):
        self.n = n
        self.nxt = {-1: n}
        self.prv = {n: -1}
        self.heap = []
        self.count = 0

    def _push(self, l, r):
        n = self.n
        if l == -1:
            if r < 1:
                return
            seat, dist = 0, r
        elif r == n:
            if l > n - 2:
                return
            seat, dist = n - 1, n - 1 - l
        else:
            if r - l < 2:
                return
            seat, dist = (l + r) // 2, (r - l) // 2
        heapq.heappush(self.heap, (-dist, seat, l, r))

    def board(self):
        n = self.n
        if self.count == 0:
            s = 0
            l, r = -1, n
        else:
            while True:
                nd, s, l, r = heapq.heappop(self.heap)
                if self.nxt.get(l) == r:
                    break
        self.count += 1
        self.nxt[l] = s
        self.nxt[s] = r
        self.prv[r] = s
        self.prv[s] = l
        self._push(l, s)
        self._push(s, r)
        return s

    def drop(self, p):
        l, r = self.prv.pop(p), self.nxt.pop(p)
        self.nxt[l] = r
        self.prv[r] = l
        self.count -= 1
        if self.count > 0:
            self._push(l, r)

def main():
    data = sys.stdin.read().split()
    n, q = int(data[0]), int(data[1])
    sh = Shuttle(n)
    pos = 2
    out = []
    for _ in range(q):
        op = data[pos]
        pos += 1
        if op == 'board':
            out.append(sh.board())
        else:
            sh.drop(int(data[pos]))
            pos += 1
    print('\n'.join(map(str, out)))

main()

